  Button auto=Ui.textButton(this,"");Runnable autoLabel=()->auto.setText("Автопереход к следующей серии: "+(library.prefs.getBoolean("auto_next",true)?"вкл":"выкл"));autoLabel.run();auto.setOnClickListener(v->{library.prefs.edit().putBoolean("auto_next",!library.prefs.getBoolean("auto_next",true)).apply();autoLabel.run();});Ui.add(panel,auto,8);
