 void renderEpisodes(){episodeStrip.removeAllViews();int at=playlist.indexOf(current),first=Math.max(0,at-3),last=Math.min(playlist.size(),Math.max(7,at+4));for(int i=first;i<last;i++){Episode episode=playlist.get(i);Button button=Ui.button(this,episode.number,false);button.setPadding(Ui.dp(this,8),0,Ui.dp(this,8),0);button.setMinWidth(Ui.dp(this,48));button.setMaxLines(1);boolean selectedEpisode=episode.id==current.id;button.setBackground(Ui.ripple(this,selectedEpisode?Ui.SOFT:Ui.PANEL,13));button.setTextColor(selectedEpisode?Ui.ACCENT:Ui.TEXT);button.setSelected(selectedEpisode);button.setContentDescription(episode.label()+(selectedEpisode?", идёт просмотр":""));LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-2,-2);ep.rightMargin=Ui.dp(this,8);episodeStrip.addView(button,ep);button.setOnClickListener(v->{if(episode.id!=current.id)navigate(episode);});}}
 void navigate(Episode episode){
  stopCountdown(null);savePosition();releaseEngine();if(pending!=null)pending.cancel(true);generation++;int session=generation;current=episode;meter.start(episode.id);awardRetryAt=0;resolved=null;failed=false;wasReady=false;desiredPlay=true;position=library.position(episode.id);removeError();voice=episode.voice;provider=episode.player;number=episode.number;playlist=Sources.episodes(videos,voice,provider);selection();int index=playlist.indexOf(episode);previous.setEnabled(index>0);next.setEnabled(index>=0&&index<playlist.size()-1);renderEpisodes();
  if(party!=null&&!applyingRemote)party.push();loadIntro(episode);
  episodeTag.setText(episode.label());currentTitle.setText(episode.label());status.setText("Открываем видео…");clock.setText("00:00 / --:--");timeline.setProgress(0);play.setEnabled(false);play.setVisibility(View.INVISIBLE);timeline.setEnabled(false);loading.setVisibility(View.VISIBLE);refreshSettings();showControls();
  pending=Api.IO.submit(()->{try{StreamResolver.Result result=StreamResolver.resolve(episode.url);runOnUiThread(()->{if(isDestroyed()||session!=generation)return;resolved=result;rendition=0;if(result.intro!=null&&!intro.has("opening")&&!intro.has("ending"))intro=result.intro;String preferred=library.prefs.getString("native_quality","");for(int i=0;i<result.streams.size();i++)if(result.streams.get(i).label.equals(preferred))rendition=i;if(started)startEngine();});}catch(Exception exception){runOnUiThread(()->{if(isDestroyed()||session!=generation)return;showError(exception instanceof IOException?exception.getMessage():"Не получилось открыть видео. Попробуй другой источник.");});}});
 }
 void startEngine(){
  if(resolved==null||!started||engine!=null||failed)return;StreamResolver.Stream stream=resolved.streams.get(rendition);int session=generation;
  DefaultHttpDataSource.Factory http=new DefaultHttpDataSource.Factory().setUserAgent(resolved.userAgent).setConnectTimeoutMs(12000).setReadTimeoutMs(18000).setAllowCrossProtocolRedirects(false).setDefaultRequestProperties(Collections.singletonMap("Referer",resolved.referer));ExoPlayer created=new ExoPlayer.Builder(this).setMediaSourceFactory(new DefaultMediaSourceFactory(http)).setSeekBackIncrementMs(10000).setSeekForwardIncrementMs(10000).build();engine=created;videoView.setPlayer(created);created.setAudioAttributes(new AudioAttributes.Builder().setUsage(C.USAGE_MEDIA).setContentType(C.AUDIO_CONTENT_TYPE_MOVIE).build(),true);created.setHandleAudioBecomingNoisy(true);created.setPlaybackSpeed(playbackSpeed);
  created.addListener(new Player.Listener(){boolean valid(){return !isDestroyed()&&session==generation&&engine==created;}
   @Override public void onPlaybackStateChanged(int state){if(!valid())return;loading.setVisibility(state==Player.STATE_BUFFERING?View.VISIBLE:View.GONE);if(state==Player.STATE_READY){if(!wasReady){position=PlaybackProgress.resume(position,created.getDuration());wasReady=true;applyingRemote=true;created.seekTo(position);party.release();}play.setEnabled(true);play.setVisibility(View.VISIBLE);timeline.setEnabled(created.isCurrentMediaItemSeekable());status.setText(Ui.voice(current.voice)+" · "+Ui.provider(current.player)+" · "+stream.label);library.opened(anime,current);refreshSettings();party.ready();}else if(state==Player.STATE_ENDED){desiredPlay=false;position=0;library.position(current.id,0);showControls();status.setText(next.isEnabled()?"Серия закончилась. Включить следующую?":"Серия закончилась");if(next.isEnabled()&&library.prefs.getBoolean("auto_next",true)&&foreground)startCountdown();}}
   @Override public void onPlayWhenReadyChanged(boolean playWhenReady,int reason){if(valid()&&reason==Player.PLAY_WHEN_READY_CHANGE_REASON_USER_REQUEST&&foreground)party.push();}
   @Override public void onPositionDiscontinuity(Player.PositionInfo oldPosition,Player.PositionInfo newPosition,int reason){if(valid()&&reason==Player.DISCONTINUITY_REASON_SEEK)party.push();}
   @Override public void onIsPlayingChanged(boolean playing){if(!valid())return;Ui.icon(play,playing?"pause":"play",0xFF15151C);play.setContentDescription(playing?"Пауза":"Воспроизвести");surface.setKeepScreenOn(playing);if(!playing)showControls();}
   @Override public void onPlayerError(PlaybackException exception){if(valid()){savePosition();showError("Не получилось воспроизвести видео. Попробуй загрузить его снова или выбери другое качество.");}}
  });wasReady=false;created.setMediaItem(new MediaItem.Builder().setUri(stream.url).setMimeType(stream.mime).build(),position);created.prepare();created.setPlayWhenReady(foreground&&desiredPlay);refreshSettings();showControls();
 }
 void refreshSettings(){String label=resolved==null?"Авто":resolved.streams.get(rendition).label;if(quality!=null){Ui.fieldValue(quality,"Качество",label);quality.setEnabled(resolved!=null&&resolved.streams.size()>1);}if(speed!=null)Ui.fieldValue(speed,"Скорость",speedLabel());if(settingsSummary!=null)settingsSummary.setText(Ui.voice(current.voice)+" · "+label+" · "+speedLabel());}
 void chooseQuality(){if(resolved==null)return;List<String>labels=new ArrayList<>();for(StreamResolver.Stream stream:resolved.streams)labels.add(stream.label);Ui.choose(this,"Качество видео",labels,resolved.streams.get(rendition).label,label->changeQuality(labels.indexOf(label)));}
 void changeQuality(int index){if(resolved==null||index<0||index>=resolved.streams.size()||(index==rendition&&!failed))return;if(engine!=null)desiredPlay=engine.getPlayWhenReady();savePosition();releaseEngine();rendition=index;failed=false;wasReady=false;removeError();loading.setVisibility(View.VISIBLE);library.prefs.edit().putString("native_quality",resolved.streams.get(index).label).apply();startEngine();refreshSettings();}
 String speedLabel(){return String.format(Locale.ROOT,"%s×",playbackSpeed==(int)playbackSpeed?Integer.toString((int)playbackSpeed):Float.toString(playbackSpeed));}
 void chooseSpeed(){List<String>labels=Arrays.asList("0.5×","0.75×","1×","1.25×","1.5×","1.75×","2×");Ui.choose(this,"Скорость воспроизведения",labels,speedLabel(),label->{playbackSpeed=Float.parseFloat(label.replace("×",""));library.prefs.edit().putFloat("native_speed",playbackSpeed).apply();if(engine!=null)engine.setPlaybackSpeed(playbackSpeed);refreshSettings();showControls();});}
 void chooseSeries(){List<Episode>options=Sources.episodes(videos,current.voice,current.player);List<String>labels=new ArrayList<>();for(Episode episode:options)labels.add(episode.label());Ui.choose(this,"Выбери серию",labels,current.label(),label->selectEpisode(options.get(labels.indexOf(label))));}
 void selectEpisode(Episode episode){if(episode.id!=current.id)navigate(episode);}
 void selection(){selected=Sources.match(videos,voice,provider,number);if(voiceButton==null)return;Ui.fieldValue(voiceButton,"Озвучка",Ui.voice(voice));Ui.fieldValue(sourceButton,"Источник",Ui.provider(provider));Ui.fieldValue(seriesButton,"Серия",selected==null?"Выбери номер":number);apply.setEnabled(selected!=null);apply.setText(selected!=null&&!StreamResolver.supports(selected.url)?"Открыть плеер сайта":"Применить");apply.setVisibility(selected==null||selected.id!=current.id?View.VISIBLE:View.GONE);}
 void move(int step){int index=playlist.indexOf(current)+step;if(index>=0&&index<playlist.size())navigate(playlist.get(index));}
 void seek(long delta){if(engine!=null&&engine.isCurrentMediaItemSeekable()){engine.seekTo(PlaybackProgress.seek(engine.getCurrentPosition(),delta,engine.getDuration()));showControls();}}
 void showControls(){if(overlay==null)return;overlay.setVisibility(View.VISIBLE);hideAt=SystemClock.uptimeMillis()+4000;}
 void updateProgress(){if(engine==null)return;long now=engine.getCurrentPosition(),duration=engine.getDuration();if(skipIntro!=null)updateSkip(now,duration);if(!dragging){clock.setText(PlaybackProgress.time(now)+" / "+(duration>0?PlaybackProgress.time(duration):"--:--"));timeline.setProgress(duration>0?(int)Math.min(10000,now*10000/duration):0);timeline.setSecondaryProgress(duration>0?(int)Math.min(10000,engine.getBufferedPosition()*10000/duration):0);}if(SystemClock.uptimeMillis()-lastSave>=5000){savePosition();lastSave=SystemClock.uptimeMillis();}}
 /** Очки за серию: учитывается только реальное воспроизведение, запрос уходит один раз на серию. */
 void watchTick(){
  if(engine==null)return;meter.tick(engine.isPlaying(),SystemClock.uptimeMillis());
  if(!account.signedIn()||!meter.due(engine.getDuration())||SystemClock.uptimeMillis()<awardRetryAt)return;
  meter.sent=true;Episode episode=current;Anime item=anime;int seconds=meter.seconds();
  Api.IO.execute(()->{try{org.json.JSONObject result=account.award(item,episode.id,episode.number,seconds);runOnUiThread(()->{if(isDestroyed())return;
    if(result.optBoolean("awarded")){int bonus=result.optInt("streak_bonus");Toast.makeText(this,"+"+result.optInt("points")+" очков"+(bonus>0?" · 🔥 "+Rewards.days(result.optInt("streak"))+" подряд (+"+bonus+")":"")+" · баланс "+Rewards.points(result.optInt("balance")),Toast.LENGTH_LONG).show();Social.announce(this,result);}
    else{String reason=Rewards.skipReason(result.optString("reason"));if(!reason.isEmpty()&&!result.optString("reason").equals("already"))Toast.makeText(this,reason,Toast.LENGTH_SHORT).show();}});}
   catch(Exception exception){runOnUiThread(()->{if(meter.episode==episode.id){meter.sent=false;awardRetryAt=SystemClock.uptimeMillis()+60000;}});}});
 }
 void startCountdown(){countdown=6;cancelAuto.setVisibility(View.VISIBLE);handler.removeCallbacks(autoNext);handler.post(autoNext);}
 void stopCountdown(String message){if(countdown>0){handler.removeCallbacks(autoNext);countdown=0;if(cancelAuto!=null)cancelAuto.setVisibility(View.GONE);if(message!=null)status.setText(message);}}
 void savePosition(){if(engine!=null&&wasReady){position=engine.getPlaybackState()==Player.STATE_ENDED?0:PlaybackProgress.resume(engine.getCurrentPosition(),engine.getDuration());library.position(current.id,position);}}
 void releaseEngine(){if(engine!=null){ExoPlayer old=engine;engine=null;videoView.setPlayer(null);old.release();}surface.setKeepScreenOn(false);}
 void removeError(){if(error!=null){surface.removeView(error);error=null;}}
 void showError(String message){failed=true;releaseEngine();loading.setVisibility(View.GONE);play.setEnabled(false);timeline.setEnabled(false);if(fullscreen)setFullscreen(false);status.setText("Видео недоступно");removeError();error=Ui.padded(this,16);error.setBackgroundColor(Ui.BG);ScrollView scroll=new ScrollView(this);LinearLayout info=Ui.column(this);info.addView(Ui.title(this,"Не получилось открыть видео",17));Ui.add(info,Ui.text(this,message,13,Ui.MUTED),8);scroll.addView(info);error.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout actions=Ui.row(this);Button retry=Ui.button(this,"Повторить",true);actions.addView(retry,new LinearLayout.LayoutParams(0,-2,1));retry.setOnClickListener(v->navigate(current));if(resolved!=null&&resolved.streams.size()>1){Button other=Ui.button(this,"Качество",false);LinearLayout.LayoutParams qp=new LinearLayout.LayoutParams(0,-2,1);qp.leftMargin=Ui.dp(this,8);actions.addView(other,qp);other.setOnClickListener(v->chooseQuality());}Ui.add(error,actions,8);surface.addView(error,new FrameLayout.LayoutParams(-1,-1));}
 void openWebsite(Episode episode){savePosition();if(engine!=null)engine.pause();startActivity(new Intent(this,WebPlayerActivity.class).putExtra("anime_id",anime.id).putExtra("video_id",episode.id));}
 void setFullscreen(boolean value){fullscreen=value;header.setVisibility(value?View.GONE:View.VISIBLE);details.setVisibility(value?View.GONE:View.VISIBLE);Ui.icon(full,value?"collapse":"fullscreen",Ui.TEXT);full.setContentDescription(value?"Выйти из полного экрана":"На весь экран");getWindow().getDecorView().setSystemUiVisibility(value?View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY:0);root.requestApplyInsets();setRequestedOrientation(value?ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE:ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED);fitSurface();showControls();}
 void fitSurface(){if(surface==null)return;LinearLayout.LayoutParams params=(LinearLayout.LayoutParams)surface.getLayoutParams();int height;float weight;if(fullscreen){height=0;weight=1;}else{float density=getResources().getDisplayMetrics().density;float width=root.getWidth()>0?root.getWidth()/density:getResources().getConfiguration().screenWidthDp;float available=root.getHeight()>0?(root.getHeight()-root.getPaddingTop()-root.getPaddingBottom())/density:getResources().getConfiguration().screenHeightDp;height=Ui.dp(this,Math.max(128,Math.min(width*9/16,(available-56)*.52f)));weight=0;}if(params.height!=height||params.weight!=weight){params.height=height;params.weight=weight;surface.setLayoutParams(params);}}
 @Override public void onConfigurationChanged(Configuration configuration){super.onConfigurationChanged(configuration);root.post(this::fitSurface);}
 @Override public void onBackPressed(){if(fullscreen)setFullscreen(false);else super.onBackPressed();}
 @Override protected void onStart(){super.onStart();started=true;if(resolved!=null)startEngine();}
 @Override protected void onResume(){super.onResume();foreground=true;if(engine!=null)engine.setPlayWhenReady(desiredPlay);}
 @Override protected void onPause(){foreground=false;stopCountdown("Серия закончилась");if(engine!=null){desiredPlay=engine.getPlayWhenReady();savePosition();engine.pause();}super.onPause();}
 @Override protected void onStop(){started=false;savePosition();releaseEngine();super.onStop();}
 @Override protected void onSaveInstanceState(Bundle state){if(current!=null)state.putLong("video_id",current.id);state.putBoolean("fullscreen",fullscreen);super.onSaveInstanceState(state);}
 @Override protected void onDestroy(){if(party!=null)party.leave();handler.removeCallbacksAndMessages(null);generation++;if(pending!=null)pending.cancel(true);if(settingsDialog!=null)settingsDialog.dismiss();if(surface!=null){savePosition();releaseEngine();}super.onDestroy();}
 /** Метки опенинга и эндинга от зрителей: кнопка пропуска ведёт точно на конец заставки. */
 void loadIntro(Episode episode){int request=++introGeneration;intro=new JSONObject();Api.IO.execute(()->{try{Object r=account.anonRpc("anime_intro",new JSONObject().put("p_anime_id",anime.id).put("p_episode",episode.number));runOnUiThread(()->{if(request==introGeneration&&r instanceof JSONObject&&(((JSONObject)r).has("opening")||((JSONObject)r).has("ending")||resolved==null||resolved.intro==null))intro=(JSONObject)r;});}catch(Exception ignored){}});}
 void updateSkip(long now,long duration){
  boolean usable=wasReady&&engine.isCurrentMediaItemSeekable();JSONObject op=intro.optJSONObject("opening"),ed=intro.optJSONObject("ending");
  if(usable&&op!=null&&now>=op.optLong("start")*1000-3000&&now<op.optLong("end")*1000-1000){long to=op.optLong("end")*1000;skipIntro.setText("Пропустить опенинг");skipIntro.setOnClickListener(v->{engine.seekTo(to);showControls();});skipIntro.setVisibility(View.VISIBLE);return;}
  if(usable&&ed!=null&&now>=ed.optLong("start")*1000&&now<ed.optLong("end")*1000-1000){long to=ed.optLong("end")*1000;boolean last=duration>0&&to>=duration-15000;skipIntro.setText(last&&next.isEnabled()?"Следующая серия":"Пропустить эндинг");skipIntro.setOnClickListener(v->{if(last&&next.isEnabled())move(1);else{engine.seekTo(to);showControls();}});skipIntro.setVisibility(View.VISIBLE);return;}
  boolean fallback=usable&&op==null&&now<300000&&(duration<=0||now+85000<duration);skipIntro.setText("+85 с");skipIntro.setOnClickListener(v->seek(85000));skipIntro.setVisibility(fallback?View.VISIBLE:View.GONE);
 }
 /** Отметить опенинг или эндинг: «начало» и «конец» берутся из текущей позиции видео. */
 void markIntro(){
  if(!account.signedIn()){Toast.makeText(this,"Войди в аккаунт, чтобы отмечать опенинги",Toast.LENGTH_SHORT).show();return;}
  if(engine==null||!wasReady){Toast.makeText(this,"Дождись загрузки видео",Toast.LENGTH_SHORT).show();return;}
  LinearLayout panel=Ui.column(this);panel.addView(Ui.text(this,"Поставь видео на начало заставки и нажми «Начало», затем на её конец — «Конец». Метки помогают всем пропускать опенинг точно.",13,Ui.MUTED));
  String[] kind={"opening"};LinearLayout kinds=Ui.row(this);Button op=Ui.chip(this,"Опенинг"),ed=Ui.chip(this,"Эндинг");kinds.addView(op);LinearLayout.LayoutParams kp=new LinearLayout.LayoutParams(-2,-2);kp.leftMargin=Ui.dp(this,8);kinds.addView(ed,kp);Ui.add(panel,kinds,12);
  Runnable paint=()->{Ui.chipState(op,kind[0].equals("opening"));Ui.chipState(ed,kind[0].equals("ending"));op.setCompoundDrawablesRelativeWithIntrinsicBounds(null,null,null,null);ed.setCompoundDrawablesRelativeWithIntrinsicBounds(null,null,null,null);};paint.run();op.setOnClickListener(v->{kind[0]="opening";paint.run();});ed.setOnClickListener(v->{kind[0]="ending";paint.run();});
  TextView range=Ui.text(this,"",15,Ui.TEXT);Ui.add(panel,range,14);
  Runnable show=()->range.setText("Начало: "+(markStart<0?"—":PlaybackProgress.time(markStart))+"   ·   сейчас "+PlaybackProgress.time(engine==null?0:engine.getCurrentPosition()));show.run();
  LinearLayout buttons=Ui.row(this);Button start=Ui.tonal(this,"Начало = сейчас"),end=Ui.button(this,"Конец = сейчас",true);buttons.addView(start,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(0,-2,1);bp.leftMargin=Ui.dp(this,8);buttons.addView(end,bp);Ui.add(panel,buttons,12);
  Dialog dialog=Ui.sheet(this,"Отметить заставку",panel,"Закрыть");
  start.setOnClickListener(v->{markStart=engine==null?0:engine.getCurrentPosition();show.run();});
  end.setOnClickListener(v->{if(engine==null)return;long finish=engine.getCurrentPosition();if(markStart<0||finish<=markStart){Toast.makeText(this,"Сначала отметь начало",Toast.LENGTH_SHORT).show();return;}long from=markStart;Episode episode=current;
   Extras.async(this,()->account.rpc("mark_intro",new JSONObject().put("p_anime_id",anime.id).put("p_episode",episode.number).put("p_kind",kind[0]).put("p_start",from/1000).put("p_end",finish/1000)),r->{if(r instanceof JSONObject&&episode==current)intro=(JSONObject)r;markStart=-1;dialog.dismiss();Toast.makeText(this,"Спасибо! Метка сохранена",Toast.LENGTH_SHORT).show();});});
 }
